O = {
"c481:xo52_2_66": ("**의료법의 목적**", "의료법 제1조의 목적은 의료에 필요한 사항을 규정해 **국민의 건강을 보호하고 증진**하는 것이에요.", "의료법의 목적은 **국민의 건강을 보호하고 증진**하는 것이다.", "의료법 = 국민 건강 보호·증진", 4),
"c481:xt52_2_66": ("의료법 **제1조**", "의료법의 목적은 **국민의 건강을 보호하고 증진**하는 것이에요.", "'의료기기 보급'으로 바꾸면 틀려요.", "의료법 = 국민 건강", 4),
"c481:xo52_2_69": ("**원격의료**의 대상", "원격의료는 의료인이 정보통신기술로 **먼 곳의 의료인**에게 의료지식·기술을 지원하는 것이에요(의료법 제34조).", "원격의료는 먼 곳의 **의료인**을 정보통신기술로 지원하는 것이다.", "원격의료 = 의료인 ↔ 의료인", 3),
"c481:xt52_2_69": ("정보통신으로 **먼 곳의 의료인** 지원", "의료법상 이것이 **원격의료**예요.", "'방문진료'로 바꾸면 틀려요.", "원격 = 의료인끼리", 3),
"c482:xo53_2_66": ("특정 질환 **고난도 의료**", "특정 진료과목·질환에 난이도 높은 의료를 하는 병원은 보건복지부장관이 지정하는 **전문병원**이에요. 요양병원은 장기 입원 요양이 목적이에요.", "특정 질환의 고난도 의료를 하는 기관은 **전문병원**이다.", "전문 = 어려운 한 분야", 3),
"c482:xo53_2_67": ("**표준업무** 고시", "의료기관 종류별 표준업무는 **보건복지부장관**이 정해 고시해요.", "표준업무는 **보건복지부장관**이 고시한다.", "기준을 정하는 건 장관", 3),
"c482:xo53_2_69": ("개설 허가 **심의 위원회**", "병원급 개설 허가를 심의하려고 시·도지사 소속으로 **의료기관개설위원회**를 둬요.", "개설 허가 심의는 **의료기관개설위원회**가 한다.", "개설 = 개설위원회", 3),
"c482:xo53_2_70": ("**휴업 신고**처", "폐업하거나 1개월 이상 휴업할 때는 관할 **시장·군수·구청장**에게 신고해요(의료법 제40조).", "휴업 신고는 **시장·군수·구청장**에게 한다.", "폐업·휴업 = 시·군·구", 4),
"c482:xo52_2_67": ("세탁물처리업 **휴업 신고**", "세탁물 처리업은 **시장·군수·구청장**에게 신고하고, 휴업·폐업도 같은 곳에 신고해요.", "세탁물처리업 휴업은 **시장·군수·구청장**에게 신고한다.", "동네 일은 시·군·구", 3),
"c482:xo51_2_69": ("**병원 개설** 허가권자", "의원급은 시장·군수·구청장에게 **신고**, 병원급은 **시·도지사 허가**예요.", "병원 개설은 **시·도지사**의 허가를 받는다.", "의원 신고(시·군·구), 병원 허가(시·도)", 5),
"c482:xo50_2_66": ("100~300병상 종합병원 **필수 진료과**", "내과·외과·소아청소년과·산부인과 중 3개와 **영상의학과·마취통증의학과·진단검사의학과(또는 병리과)** 를 갖춰야 해요. 맞는 문장이에요.", "'영상의학과는 선택'이라고 하면 틀려요.", "영상·마취·진단검사는 필수", 3),
"c482:xo50_2_67": ("간호·간병통합서비스 **대상**", "노력 대상은 병원·치과병원·한방병원·종합병원이에요. **요양병원은 빠져요**.", "간호·간병통합서비스 노력 대상에 요양병원은 **포함되지 않는다**.", "요양병원은 제외", 3),
"c482:xo50_2_69": ("시정명령 **불이행**", "시정명령 불이행은 개설허가 취소 **또는** 업무정지 대상이에요. 반드시 취소하는 것은 아니에요.", "시정명령 불이행 시 **취소 또는 업무정지**를 할 수 있다.", "불이행 = 취소 또는 정지", 3),
"c483:xo51_2_67": ("간호기록부 **보존기간**", "간호기록부는 **5년**, 처방전은 **2년**이에요.", "간호기록부의 보존기간은 **5년**이다.", "처방전 2, 간호기록 5, 진료기록 10", 5),
"c483:xt51_2_67": ("보존기간 **2년** 기록", "보존기간이 2년인 것은 **처방전**이에요.", "'간호기록부'로 바꾸면 틀려요(5년).", "처방전 2년", 5),
"c484:xo53_2_68": ("**정신질환자** 결격의 예외", "정신질환자라도 **전문의가 의료인으로 적합하다고 인정하면** 결격이 아니에요(의료법 제8조).", "전문의가 적합 판정한 정신질환자는 결격이 **아니다**.", "전문의 OK면 예외", 4),
"c484:xo52_2_68": ("외국 면허자 **승인권자**", "외국 면허 소지자가 국내에서 교육·연구 등으로 의료행위를 하려면 **보건복지부장관** 승인을 받아요.", "외국 면허자는 **보건복지부장관**의 승인을 받는다.", "면허·의료 = 복지부", 3),
"c484:xo51_2_66": ("**물리치료사**의 법적 지위", "의료법상 의료인은 의사·치과의사·한의사·조산사·간호사 5종이에요. 물리치료사는 의료기사법의 **의료기사**예요.", "물리치료사는 **의료기사**다(의료인이 아님).", "의료인 5종: 의·치·한·조·간", 5),
"c484:xo51_2_68": ("조산사와 **사망진단서**", "조산사는 직접 조산한 경우의 출생·사망·사산 **증명서**만 가능하고, 사망**진단서**는 의사·치과의사·한의사만 발급해요.", "조산사는 사망진단서를 발급할 수 **없다**.", "진단서 = 의·치·한, 조산사 = 증명서", 4),
"c484:xo50_2_68": ("의료인 국가시험 **필요 사항**", "의료인 국가시험의 시행 등에 필요한 사항은 **대통령령**으로 정해요(의료법 제9조).", "의료인 국가시험에 필요한 사항은 **대통령령**으로 정한다.", "의료인 국시 = 대통령령", 3),
"c485:xo52_2_70": ("기물 파괴·점거 **진료 방해**", "의료기관 기물 파괴·점거로 진료를 방해하면 **5년 이하 징역 또는 5천만 원 이하 벌금**이에요.", "진료 방해는 **5년 이하 징역 또는 5천만 원 이하 벌금**이다.", "진료 방해 5년·5천", 4),
"c485:xt52_2_70": ("진료 방해 **벌칙**", "**5년 이하 징역 / 5천만 원 이하 벌금**이에요.", "'1년 이하 징역'으로 바꾸면 틀려요.", "5년·5천", 4),
"c485:xo51_2_70": ("**비의료인 개설** 벌칙", "개설 자격이 없는 자가 의료기관을 개설하면 **10년 이하 징역 또는 1억 원 이하 벌금**이에요.", "비의료인 개설은 **10년 이하 징역 또는 1억 원 이하 벌금**이다.", "사무장병원 10년·1억", 4),
"c485:xt51_2_70": ("개설 자격 없는 자 **개설 벌칙**", "**10년 이하 징역 / 1억 원 이하 벌금**이에요.", "'1년 이하 징역'으로 바꾸면 틀려요.", "10년·1억", 4),
"c485:xo50_2_70": ("진료 중 폭행 **상해**", "의료인 폭행으로 상해에 이르면 **7년 이하 징역 또는 1천만~7천만 원 벌금**이에요.", "진료 중 폭행으로 상해를 입히면 **7년 이하** 징역에 처한다.", "상해 7년", 3),
"c485:xt50_2_70": ("폭행 **상해** 처벌", "**7년 이하 징역 또는 1천만~7천만 원 벌금**이에요.", "'1년 이하 징역'으로 바꾸면 틀려요.", "상해 7년", 3),
"c486:xo53_2_71": ("**감각·지각·활동훈련**", "감각·지각·활동훈련은 **작업치료사** 업무예요. 물리치료사는 온열·전기·광선·수치료, 마사지·기능훈련·신체교정운동 등을 해요.", "감각·지각·활동훈련은 **작업치료사** 업무다.", "감각·지각 = 작업치료", 4),
"c486:xo53_2_72": ("의료기사 **업무 범위**", "의료기사의 업무 범위와 한계는 **대통령령**(의료기사법 시행령)으로 정해요.", "업무 범위는 **대통령령**으로 정한다.", "업무 범위 = 대통령령", 4),
"c486:xo52_2_71": ("**의료기사**의 정의", "의료기사는 의사·치과의사의 지도를 받아 **진료나 의화학적 검사**에 종사하는 사람이에요. 의무기록은 보건의료정보관리사예요.", "의료기사는 **진료나 의화학적 검사**에 종사하는 사람이다.", "의료기사 = 진료·검사 보조", 3),
"c486:xo52_2_73": ("**면허 발급 전** 업무", "국시에 합격해도 면허를 받기 전에는 업무를 할 수 **없어요**. 실습생만 예외예요.", "면허 발급 전에는 업무를 할 수 **없다**.", "면허가 있어야 일한다", 3),
"c486:xo51_2_71": ("**안경사**의 지위", "안경사는 **'의료기사 등'** 에 포함되지만 의료기사는 아니에요.", "안경사는 의료기사가 **아니다**(의료기사 '등'에 포함).", "'등'에 들어가는 안경사·보건의료정보관리사", 3),
"c486:xo50_2_71": ("의료기사법의 **목적**", "의료기사법은 의료기사 등의 **자격·면허** 등에 필요한 사항을 정해 국민 보건에 이바지하는 것이 목적이에요.", "의료기사법은 의료기사 등의 **자격·면허** 등을 정하는 것이 목적이다.", "의료기사법 = 자격·면허", 3),
"c487:xo53_2_73": ("면허증 **재발급** 신청처", "면허를 내주는 **보건복지부장관**에게 재발급도 신청해요.", "면허증 재발급 신청서는 **보건복지부장관**에게 낸다.", "면허 = 장관", 4),
"c487:xt53_2_73": ("면허증 분실 **재발급**", "재발급 신청서는 **보건복지부장관**에게 내요.", "'보건소장'으로 바꾸면 틀려요.", "면허 = 장관", 4),
"c487:xo52_2_72": ("출제방법·**배점비율**", "시험 실무는 위탁받은 **국가시험관리기관의 장**(국시원장)이 정해요.", "출제방법·배점비율은 **국가시험관리기관의 장**이 정한다.", "시험 실무 = 국시원", 3),
"c487:xt52_2_72": ("국가시험 **시행 사항** 결정자", "**국가시험관리기관의 장**이 정해요.", "'행정안전부장관'으로 바꾸면 틀려요.", "시험 = 국시원장", 3),
"c487:xo51_2_73": ("**피한정후견인**", "피성년후견인·**피한정후견인**은 의료기사 결격사유예요.", "피한정후견인은 의료기사 **결격사유다**.", "후견인 = 결격", 4),
"c487:xt51_2_73": ("결격사유가 **아닌 것**", "**지체장애**는 결격사유가 아니에요.", "'피한정후견인'으로 바꾸면 틀려요.", "몸의 장애는 결격 아님", 4),
"c487:xo50_2_73": ("**실태 신고** 주기", "물리치료사는 면허 후 **3년마다** 실태·취업상황을 신고해요.", "물리치료사는 **3년마다** 실태를 신고한다.", "신고 3년", 4),
"c487:xt50_2_73": ("실태·취업상황 **신고처**", "**보건복지부장관**에게 신고해요.", "'시·도지사'로 바꾸면 틀려요.", "신고 = 장관", 4),
"c488:xo53_2_74": ("신규 면허 해 **보수교육**", "신규 면허를 받은 해에는 보수교육이 **면제**돼요.", "신규 면허를 받은 해에는 보수교육이 **면제**된다.", "면제: 대학원·군·신규·장관 인정", 4),
"c488:xt53_2_74": ("면제 사유가 **아닌 것**", "업무 미종사 6개월 이상은 면제가 아니라 **유예** 사유예요.", "'신규 면허'로 바꾸면 틀려요(면제 사유).", "미종사 = 유예", 4),
"c488:xo52_2_74": ("**유예 3년 이상** 후 복귀", "유예기간이 3년 이상이면 복귀 전 **20시간 이상** 받아야 해요. 8시간은 매년 기본 시간이에요.", "5년 유예 후 복귀 시 **20시간 이상**을 받아야 한다.", "매년 8, 장기 유예 후 20", 3),
"c488:xt52_2_74": ("장기 유예 후 **보수교육 시간**", "3년 이상 유예된 뒤 복귀하면 **20시간 이상**이에요.", "'8시간'으로 바꾸면 틀려요.", "유예 3년+ = 20시간", 3),
"c489:xo53_2_75": ("**면허 대여**", "면허 대여는 자격정지가 아니라 **면허 취소** 사유예요.", "면허 대여는 **면허 취소** 사유다.", "빌려주면 취소", 5),
"c489:xt53_2_75": ("**자격정지** 사유", "검사 결과를 사실과 다르게 판시하는 것은 **품위 손상**으로 자격정지 사유예요.", "'면허 대여'로 바꾸면 틀려요(취소 사유).", "거짓 판시 = 정지", 4),
"c489:xo51_2_72": ("**자격정지** 기간", "보건복지부장관은 **6개월 이내**로 면허자격을 정지할 수 있어요.", "의료기사 자격정지는 **6개월 이내**다.", "정지 6개월", 4),
"c489:xt51_2_72": ("자격정지 **기간**", "**6개월 이내**예요.", "'1년 이내'로 바꾸면 틀려요.", "정지 6개월", 4),
"c489:xo51_2_74": ("면허 대여와 **품위손상**", "면허 대여는 품위손상이 아니라 **면허 취소** 사유예요.", "면허 대여는 **면허 취소** 사유다.", "빌려주면 취소", 5),
"c489:xt51_2_74": ("**품위손상** 행위 예", "**검사 결과를 사실과 다르게 판시**하는 것이 품위손상이에요.", "'면허 대여'로 바꾸면 틀려요.", "거짓 판시 = 품위손상", 4),
"c489:xo50_2_74": ("면허증 **대여**", "면허증을 빌려주면 **면허 취소** 사유예요.", "면허증을 빌려주면 **면허 취소** 사유다.", "빌려주면 취소", 5),
"c489:xt50_2_74": ("**자격정지** 사유 예", "**검사 결과를 사실과 다르게 판시**하는 것이에요.", "'면허 대여'로 바꾸면 틀려요.", "거짓 판시 = 정지", 4),
"c490:xo53_2_76": ("**명칭 사용** 위반", "의료기사가 아닌데 명칭을 쓰면 **500만 원 이하 벌금**이에요. 3년 징역·3천만 원은 무면허 업무·면허 대여예요.", "명칭 사용 위반은 **500만 원 이하 벌금**이다.", "명칭 500만, 무면허·대여 3년·3천", 4),
"c490:xo52_2_75": ("**면허 대여** 벌칙", "면허 대여·대여받기·알선은 **3년 이하 징역 또는 3천만 원 이하 벌금**이에요.", "면허 대여는 **3년 이하 징역 또는 3천만 원 이하 벌금**이다.", "대여 3년·3천", 4),
"c490:xo51_2_75": ("**무면허 업무**", "무면허로 의료기사 업무를 하면 **3년 이하 징역 또는 3천만 원 이하 벌금**으로, 과태료가 아닌 형벌 대상이에요.", "무면허 업무는 **3년 이하 징역 또는 3천만 원 이하 벌금** 대상이다.", "무면허 3년·3천", 4),
"c490:xo50_2_75": ("**비밀 누설**", "업무상 비밀 누설은 **3년 이하 징역·3천만 원 이하 벌금**(형벌)이에요. 과태료는 보수교육 시정명령 불이행 등이에요.", "비밀 누설은 **형벌(3년 이하 징역·3천만 원 이하 벌금)** 대상이다.", "비밀 누설 3년·3천", 4),
"c491:xo53_2_79": ("성범죄자 **취업 제한** 기간", "법원이 형과 함께 **10년 이내**의 취업제한명령을 선고해요.", "성범죄자의 장애인시설 취업 제한은 **10년 이내**다.", "취업제한 10년", 3),
"c491:xt53_2_79": ("취업 제한 **기간**", "**최대 10년**이에요.", "'5년'으로 바꾸면 틀려요.", "10년", 3),
"c491:xo50_2_78": ("장애인학대 **취업제한**", "법원은 **10년 이내**의 취업제한명령을 함께 선고해요.", "장애인학대 범죄자의 취업제한 기간은 최대 **10년**이다.", "10년", 3),
"c491:xt50_2_78": ("취업제한 **최대 기간**", "**10년**이에요.", "'3년'으로 바꾸면 틀려요.", "10년", 3),
"c492:xo53_2_80": ("**진단·판정** 서비스 시설", "입원·통원으로 상담·진단·판정·치료를 하는 것은 **장애인 의료재활시설**이에요. 거주시설은 생활하는 곳이에요.", "진단·판정 서비스는 **장애인 의료재활시설**이 제공한다.", "의료재활 = 진단·치료", 3),
"c492:xt53_2_80": ("입원·통원 **상담·진단·재활**", "**장애인 의료재활시설**이에요.", "'장애인 거주시설'로 바꾸면 틀려요.", "의료재활 = 진단·치료", 3),
"c492:xo52_2_78": ("민간 장애인복지시설 **신고처**", "국가·지자체가 아닌 자는 관할 **시장·군수·구청장**에게 신고해요.", "민간 장애인복지시설은 **시장·군수·구청장**에게 신고한다.", "시설 신고 = 시·군·구", 3),
"c492:xt52_2_78": ("민간 시설 **설치 신고**", "**시장·군수·구청장**에게 해요.", "'보건소장'으로 바꾸면 틀려요.", "시·군·구", 3),
"c492:xo51_2_78": ("**여가·사회참여** 지원 시설", "여가·사회참여를 지원하는 것은 장애인복지관 같은 **장애인 지역사회재활시설**이에요. 의료재활시설은 진단·치료 중심이에요.", "여가·사회참여 지원 시설은 **장애인 지역사회재활시설**이다.", "지역사회 = 복지관", 3),
"c492:xt51_2_78": ("상담·치료·**여가·사회참여**", "**장애인 지역사회재활시설**이에요.", "'의료재활시설'로 바꾸면 틀려요.", "지역사회 = 복지관", 3),
"c493:xo53_2_77": ("**장애인**의 정의", "장애인은 **신체적·정신적** 장애로 오랫동안 일상·사회생활에 상당한 제약을 받는 자예요.", "장애인은 **신체적·정신적** 장애를 모두 포함한다.", "신체 + 정신", 3),
"c493:xo53_2_78": ("장애아동 **수당**", "18세 미만 장애아동에게는 **장애아동수당**, 18세 이상에게는 장애수당을 줘요.", "장애아동에게는 **장애아동수당**을 지급한다.", "아동 = 장애아동수당", 3),
"c493:xo52_2_76": ("장애인정책조정위원회 **소속**", "여러 부처를 조정해야 하므로 **국무총리** 소속이에요.", "장애인정책조정위원회는 **국무총리** 소속이다.", "조정 = 총리", 4),
"c493:xo52_2_77": ("장애 정도 **정밀심사**", "시장·군수·구청장은 **국민연금공단**에 정밀심사를 의뢰할 수 있어요.", "장애 정도 정밀심사는 **국민연금공단**이 맡는다.", "장애 심사 = 연금공단", 3),
"c493:xo51_2_76": ("**내부기관** 장애", "외부 신체 기능과 내부기관 장애는 **신체적 장애**예요. 정신적 장애는 발달장애·정신질환으로 인한 장애예요.", "내부기관의 장애는 **신체적 장애**에 해당한다.", "몸 안팎 = 신체적", 3),
"c493:xo50_2_76": ("장애인복지법 **기본이념**", "기본이념은 장애인의 완전한 사회 참여와 평등을 통한 **사회통합**이에요.", "장애인복지법의 기본이념은 **사회통합**이다.", "기본이념 = 사회통합", 4),
"c493:xo50_2_77": ("**장애인등록증** 발급", "등록증은 **시장·군수·구청장** 등이 발급해요.", "장애인등록증은 **시장·군수·구청장**이 발급한다.", "등록 = 시·군·구", 3),
"c496:xo51_2_77": ("**장애실태조사**", "장애실태조사는 **보건복지부장관이 3년마다** 해요(장애인복지법 제31조).", "장애실태조사는 **보건복지부장관이 3년마다** 실시한다.", "실태조사 3년, 장관", 3),
"c494:xo52_2_82": ("노인 이용 **구걸**", "노인을 이용한 구걸은 **금지행위**예요.", "노인을 이용한 구걸은 **금지행위다**.", "학대·구걸·성희롱·착취 = 금지", 3),
"c494:xt52_2_82": ("금지행위가 **아닌 것**", "노인이 **자유의사로 합의**한 행위는 금지행위가 아니에요.", "'노인을 이용한 구걸'로 바꾸면 틀려요.", "합의하면 금지 아님", 3),
"c494:xo50_2_79": ("**방임**과 노인학대", "노인학대에는 폭력·착취·가혹행위·유기 **또는 방임**이 포함돼요.", "방임은 노인학대에 **포함된다**.", "내버려 두는 것도 학대", 3),
"c494:xt50_2_79": ("폭력·착취·**방임**", "이를 모두 뜻하는 용어가 **노인학대**예요.", "'노인 금지행위'로 바꾸면 틀려요.", "방임도 학대", 3),
"c495:xo53_2_83": ("교양·취미 **서비스**", "교양·취미·사회참여 서비스는 여가복지시설인 **노인복지관**이에요. 노인복지주택은 주거복지시설이에요.", "교양·취미 서비스 제공 시설은 **노인복지관**이다.", "여가 = 복지관·경로당·노인교실", 3),
"c495:xo53_2_84": ("**식사 준비·청소**", "가사 지원과 신체활동 지원은 **방문요양**이에요. 방문간호는 간호·진료 보조 중심이에요.", "식사 준비와 청소는 **방문요양**이 돕는다.", "요양 = 생활, 간호 = 의료", 3),
"c495:xo52_2_81": ("**학습 프로그램** 시설", "학습 프로그램을 제공하는 것은 여가복지시설인 **노인교실**이에요.", "학습 프로그램 제공 시설은 **노인교실**이다.", "교실 = 배움", 3),
"c495:xo51_2_81": ("**노인공동생활가정**", "노인공동생활가정은 **주거복지시설**이에요.", "노인공동생활가정은 **노인주거복지시설**이다.", "공동생활 = 주거", 3),
"c495:xo51_2_82": ("노인복지시설 **종류**", "노인복지시설은 주거·의료·여가·재가복지시설, 노인보호전문기관, 노인일자리지원기관, 학대피해노인 전용쉼터예요. **재활복지시설은 없어요**.", "노인재활복지시설은 노인복지법상 노인복지시설이 **아니다**.", "주거·의료·여가·재가", 3),
"c495:xo50_2_81": ("**재가노인복지시설** 서비스", "재가 서비스에는 방문요양·방문간호·방문목욕·주야간보호·**단기보호**가 있어요. 맞는 문장이에요.", "'단기보호는 의료복지시설 서비스'라고 하면 틀려요.", "재가 = 집에서·잠깐 맡기기", 3),
"c495:xo50_2_82": ("**신체활동 지원** 전문 인력", "노인의 신체활동·가사활동 지원을 전문으로 하는 사람은 **요양보호사**예요.", "신체활동 지원을 전문으로 하는 사람은 **요양보호사**다.", "돌봄 = 요양보호사", 3),
"c496:xo53_2_81": ("노인복지법의 **목적**", "노인복지법의 목적은 노인 질환 예방·치료, 생활 안정 등으로 **노인의 보건복지 증진**에 이바지하는 것이에요.", "노인복지법의 목적은 **노인의 보건복지 증진**이다.", "노인 = 보건복지 증진", 3),
"c496:xo53_2_82": ("상담·지도 **공무원**", "시·군·구에 두는 것은 **노인복지상담원**이에요. '노인요양상담원'은 없어요.", "노인복지법상 상담·지도 공무원은 **노인복지상담원**이다.", "노인복지상담원", 2),
"c496:xo52_2_79": ("시책 추진 **책임**", "노인 보건·복지 증진 시책은 **국가와 지방자치단체**의 책임이에요.", "노인복지 시책 추진 책임은 **국가와 지방자치단체**에 있다.", "책임 = 국가·지자체", 3),
"c496:xo52_2_80": ("노인 **건강진단** 주기", "65세 이상에게 **2년에 1회 이상** 건강진단을 실시할 수 있어요.", "노인 건강진단은 **2년에 1회 이상** 실시한다.", "2년에 1번", 4),
"c496:xo51_2_79": ("**부양의무자** 범위", "부양의무자는 **배우자와 직계비속 및 그 배우자**예요. 직계존속은 포함되지 않아요.", "부양의무자에 직계존속은 **포함되지 않는다**.", "배우자 + 자녀(와 그 배우자)", 3),
"c496:xo50_2_80": ("노인 **건강진단** 횟수", "**2년에 1회 이상**이에요.", "노인 건강진단은 **2년에 1회 이상** 실시한다.", "2년에 1번", 4),
"c497:xo52_2_84": ("**현역병**과 직장가입자", "현역병·간부후보생·비상근 근로자 등은 직장가입자에서 **제외**돼요.", "현역병은 직장가입자에서 **제외**된다.", "군인(현역병)은 빠진다", 3),
"c497:xo51_2_83": ("국민건강보험법 **목적**", "국민건강보험법의 목적은 **국민보건 향상과 사회보장 증진**이에요.", "국민건강보험법의 목적은 **국민보건 향상과 사회보장 증진**이다.", "건보 = 국민보건 + 사회보장", 3),
"c497:xo51_2_84": ("피부양자 **사망 시** 자격 상실", "사망·국적 상실·국외 거주는 **그 다음 날** 자격을 잃어요.", "피부양자는 사망한 **다음 날** 자격을 잃는다.", "사망은 다음 날", 4),
"c497:xo50_2_83": ("**사용자**의 정의", "보수를 받는 사람은 **근로자**예요. 사용자는 근로자를 고용하는 쪽이에요.", "근로의 대가로 보수를 받는 사람은 **근로자**다.", "받는 쪽 근로자, 주는 쪽 사용자", 3),
"c497:xo50_2_84": ("자격 변동 **신고 기한**", "가입자 자격이 바뀌면 **14일 이내**에 신고해요.", "건강보험 자격이 바뀌면 **14일 이내**에 신고한다.", "자격 변동 14일", 4),
"c498:xo52_2_85": ("보험급여 **정지 대상**", "급여 정지는 **국외 체류**·현역병 등이에요. 신생아는 해당하지 않아요.", "보험급여 정지 대상은 **국외 체류자** 등이다.", "정지 = 국외·군대·교도소", 3),
"c498:xt52_2_85": ("**급여 정지** 대상", "**국외 체류자**가 급여 정지 대상이에요.", "'신생아'로 바꾸면 틀려요.", "국외 = 정지", 3),
"c498:xo51_2_85": ("**이송**과 요양급여", "진찰·검사·처치·입원·간호·**이송**은 모두 요양급여예요.", "이송은 요양급여 **대상이다**.", "이송도 급여", 3),
"c498:xt51_2_85": ("요양급여가 **아닌 것**", "**퇴원**은 요양급여 항목이 아니에요.", "'이송'으로 바꾸면 틀려요.", "이송은 급여, 퇴원은 아님", 3),
"c498:xo50_2_85": ("요양기관 **현황 신고**처", "처음 요양급여비용을 청구할 때 현황을 **건강보험심사평가원**에 신고해요.", "요양기관 현황 신고는 **건강보험심사평가원**에 한다.", "현황·심사 = 심평원", 3),
"c498:xt50_2_85": ("첫 청구 **현황 신고**", "**건강보험심사평가원**에 신고해요.", "'관할 보건소'로 바꾸면 틀려요.", "심평원", 3),
"c499:xo53_2_85": ("건강보험정책심의위원회 **위원장**", "위원장은 **보건복지부차관**이에요(국민건강보험법 제4조).", "건강보험정책심의위원회 위원장은 **보건복지부차관**이다.", "건정심 = 차관", 4),
"c499:xt53_2_85": ("건정심 **위원장**", "**보건복지부차관**이에요.", "'보건복지부장관'으로 바꾸면 틀려요.", "건정심 = 차관", 4),
}
